{
  "cases": [
    {
      "id": "NREG-01",
      "invariants": [
        {
          "index": 0,
          "source_quotes": [
            "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section"
          ],
          "claim_ids": ["N002"],
          "rationale": "Claim N002 accurately records the requirement using disjunctive logic ('one or more of the documents listed in this section') rather than requiring all categories.",
          "status": "pass"
        },
        {
          "index": 1,
          "source_quotes": [
            "(a) Name change orders; or",
            "(b) Divorce decrees;",
            "(2) Certificates of naturalization;",
            "(3) Marriage certificates;",
            "(4) Documentation demonstrating change of name by operation of state law; or",
            "(5) Documentation of customary usage."
          ],
          "claim_ids": ["N002"],
          "rationale": "All six distinct leaf document options are retained in N002's choice structure and text.",
          "status": "pass"
        },
        {
          "index": 2,
          "source_quotes": [
            "(1) Court orders or decrees:\n\n(a) Name change orders; or\n\n(b) Divorce decrees;"
          ],
          "claim_ids": ["N002"],
          "rationale": "N002 preserves Court orders or decrees as the parent category grouping the two sub-alternatives of name change orders and divorce decrees.",
          "status": "pass"
        },
        {
          "index": 3,
          "source_quotes": [
            "(see an exception for married names in 8 FAM 403.1-4(C))"
          ],
          "claim_ids": ["N002"],
          "rationale": "N002 preserves the married-name exception reference as a cited remote reference without inferring a blanket exemption for all married applicants.",
          "status": "pass"
        },
        {
          "index": 4,
          "source_quotes": [
            "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
          ],
          "claim_ids": ["N002"],
          "rationale": "22 CFR 51.25 is retained as an explicit legal reference and context citation governing the acceptable documentation options.",
          "status": "pass"
        }
      ],
      "negative_controls": [
        {
          "index": 0,
          "source_quotes": [
            "must be documented by submission of one or more of the documents listed in this section"
          ],
          "claim_ids": [],
          "rationale": "The negative control incorrectly asserts that an applicant must submit documents across every listed category conjunctively, directly contradicting the source's 'one or more' standard.",
          "status": "pass"
        }
      ],
      "uncertainty": "Remote reference 8 FAM 403.1-4(C) is external to the excerpt and properly left unresolved."
    },
    {
      "id": "NREG-02",
      "invariants": [
        {
          "index": 0,
          "source_quotes": [
            "If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change"
          ],
          "claim_ids": ["N007", "E006"],
          "rationale": "The draft incorporates the parent clause regarding material name change more than one year prior to DS-11 with un-updated ID directly into the scope of the emergency issuance permission.",
          "status": "pass"
        },
        {
          "index": 1,
          "source_quotes": [
            "If there is insufficient time to request that the applicant submit acceptable ID prior to urgent or emergency travel"
          ],
          "claim_ids": ["N007", "E006"],
          "rationale": "The permission requires insufficient time to request acceptable ID prior to urgent or emergency travel, which is faithfully captured with OR logic in choice_text and scope.",
          "status": "pass"
        },
        {
          "index": 2,
          "source_quotes": [
            "a limited-validity passport may be issued in the requested name;"
          ],
          "claim_ids": ["N007", "E006"],
          "rationale": "The draft reflects discretionary modality ('may') for issuing a limited-validity passport specifically in the requested name.",
          "status": "pass"
        },
        {
          "index": 3,
          "source_quotes": [
            "you must suspend the application to request an acceptable ID in the new name."
          ],
          "claim_ids": ["N006", "E005"],
          "rationale": "The mandatory suspension duty is isolated into its own claim with 'must' modality.",
          "status": "pass"
        }
      ],
      "negative_controls": [
        {
          "index": 0,
          "source_quotes": [
            "If there is insufficient time to request that the applicant submit acceptable ID prior to urgent or emergency travel, a limited-validity passport may be issued in the requested name;"
          ],
          "claim_ids": [],
          "rationale": "The negative control erroneously claims officials 'must' issue a passport whenever urgent travel is planned, ignoring the discretionary 'may', the limited-validity restriction, and the prerequisite condition of an un-updated name change over one year prior.",
          "status": "pass"
        }
      ],
      "uncertainty": "None observed."
    },
    {
      "id": "NREG-03",
      "invariants": [
        {
          "index": 0,
          "source_quotes": [
            "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name."
          ],
          "claim_ids": ["N009", "E008"],
          "rationale": "The draft accurately captures the absence of duty for applicants with a recent name change within one year using exemption kind and not_required modality.",
          "status": "pass"
        },
        {
          "index": 1,
          "source_quotes": [
            "However, if the ID has not yet been changed, they must submit their name change documentation."
          ],
          "claim_ids": ["N010", "E009"],
          "rationale": "The contingent requirement to submit name change documentation when ID has not yet been updated is retained as a distinct requirement claim with must modality.",
          "status": "pass"
        },
        {
          "index": 2,
          "source_quotes": [
            "do not need to submit ID in the new name."
          ],
          "claim_ids": ["N009", "E008"],
          "rationale": "The draft represents the rule as not_required, avoiding mischaracterization as a requirement, prohibition, or mere permission.",
          "status": "pass"
        },
        {
          "index": 3,
          "source_quotes": [
            "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name."
          ],
          "claim_ids": ["N009", "E008"],
          "rationale": "The absence of duty is represented using standard exemption/not_required schema constructs without losing source content.",
          "status": "pass"
        },
        {
          "index": 4,
          "source_quotes": [
            "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name. However, if the ID has not yet been changed, they must submit their name change documentation."
          ],
          "claim_ids": ["N006", "N009", "N010", "E005", "E008", "E009"],
          "rationale": "The exemption is segregated from the separate >1 year suspension rule and from the documentation requirement.",
          "status": "pass"
        }
      ],
      "negative_controls": [],
      "uncertainty": "None observed."
    },
    {
      "id": "NREG-04",
      "invariants": [
        {
          "index": 0,
          "source_quotes": [
            "The court order or decree must list both the applicant's current and former name(s)."
          ],
          "claim_ids": ["E014"],
          "rationale": "E014 captures the mandatory requirement that the court order or decree list both current and former names.",
          "status": "pass"
        },
        {
          "index": 1,
          "source_quotes": [
            "EXCEPTION: You may receive a court order in which the applicant's former name is made confidential (e.g., California's Safe at Home program)."
          ],
          "claim_ids": ["E014", "E015"],
          "rationale": "The draft fails to link or model the confidential former name provision as an exception qualifying the court document content rule in E014; E014 remains completely unqualified.",
          "status": "fail"
        },
        {
          "index": 2,
          "source_quotes": [
            "EXCEPTION: You may receive a court order in which the applicant's former name is made confidential (e.g., California's Safe at Home program)."
          ],
          "claim_ids": ["E015"],
          "rationale": "The draft avoids creating an independent legal permission claim from the descriptive phrase 'You may receive'.",
          "status": "pass"
        },
        {
          "index": 3,
          "source_quotes": [
            "When this occurs, the applicant must provide both her/his current and former names on the application."
          ],
          "claim_ids": ["E015"],
          "rationale": "E015 models the application disclosure duty as a must requirement governing when this confidentiality scenario occurs.",
          "status": "pass"
        },
        {
          "index": 4,
          "source_quotes": [
            "You may request additional evidence of U.S. citizenship/non-citizen U.S. nationality or identity in accordance with 22 CFR 51.23 and 22 CFR 51.45."
          ],
          "claim_ids": ["E016"],
          "rationale": "E016 faithfully represents the permission to request additional evidence of citizenship/nationality or identity under both cited regulations.",
          "status": "pass"
        },
        {
          "index": 5,
          "source_quotes": [
            "The court order or decree must list both the applicant's current and former name(s).\n\nEXCEPTION: You may receive a court order in which the applicant's former name is made confidential (e.g., California's Safe at Home program)."
          ],
          "claim_ids": ["E014", "E015"],
          "rationale": "There is no modifier/exception relation link pointing from the exception to the court-document rule E014 in the draft.",
          "status": "fail"
        }
      ],
      "negative_controls": [],
      "uncertainty": "The draft fails to instantiate an exception claim targeting E014, placing the exception text only in context_quotes of E015."
    },
    {
      "id": "NREG-05",
      "invariants": [
        {
          "index": 0,
          "source_quotes": [
            "The applicant may not continue to use a previous name after a material name change unless the name change documentation specifically permits the applicant to continue using that name"
          ],
          "claim_ids": ["E003", "E004"],
          "rationale": "E004 is properly linked via target_ids to E003, correctly modifying the prohibition on continued use of a previous name.",
          "status": "pass"
        },
        {
          "index": 1,
          "source_quotes": [
            "You must clear the applicant's pending name even though the name change is not final and even if the passport is not being issued at this time."
          ],
          "claim_ids": ["E004", "E013"],
          "rationale": "E004 does not target or excuse E013 (the pending name clearance duty).",
          "status": "pass"
        },
        {
          "index": 2,
          "source_quotes": [
            "unless the name change documentation specifically permits the applicant to continue using that name"
          ],
          "claim_ids": ["E004"],
          "rationale": "Target validation confirms semantic congruence between the exception and the prohibited action (continuing to use a previous name).",
          "status": "pass"
        }
      ],
      "negative_controls": [
        {
          "index": 0,
          "source_quotes": [
            "The applicant may not continue to use a previous name after a material name change unless the name change documentation specifically permits the applicant to continue using that name",
            "You must clear the applicant's pending name even though the name change is not final and even if the passport is not being issued at this time."
          ],
          "claim_ids": [],
          "rationale": "The synthetic negative example incorrectly links the documentation exception to the pending-name clearance rule rather than the previous-name use prohibition.",
          "status": "pass"
        }
      ],
      "uncertainty": "None observed."
    },
    {
      "id": "NREG-06",
      "invariants": [
        {
          "index": 0,
          "source_quotes": [
            "The court order or decree must be final:"
          ],
          "claim_ids": ["E010"],
          "rationale": "E010 frames finality as a mandatory state constraint on the court order or decree.",
          "status": "pass"
        },
        {
          "index": 1,
          "source_quotes": [
            "An applicant with a pending name change must not be issued a passport in her/his new name.",
            "An applicant with a pending name change must not be issued a form FS-240 in her/his new name."
          ],
          "claim_ids": ["E011", "E012"],
          "rationale": "Passport and FS-240 issuance prohibitions are captured as separate claims E011 and E012.",
          "status": "pass"
        },
        {
          "index": 2,
          "source_quotes": [
            "You must clear the applicant's pending name even though the name change is not final and even if the passport is not being issued at this time."
          ],
          "claim_ids": ["E013"],
          "rationale": "E013 preserves pending name clearance as a mandatory duty under modality 'must'.",
          "status": "pass"
        },
        {
          "index": 3,
          "source_quotes": [
            "even though the name change is not final and even if the passport is not being issued at this time."
          ],
          "claim_ids": ["E013"],
          "rationale": "The concessive 'even though' and 'even if' clauses are retained as reinforcing conditions within logic_text rather than negative exceptions.",
          "status": "pass"
        },
        {
          "index": 4,
          "source_quotes": [
            "An applicant with a pending name change must not be issued a passport in her/his new name."
          ],
          "claim_ids": ["E011"],
          "rationale": "E011 limits the prohibition strictly to issuance 'in her/his new name', avoiding an overbroad ban on all passport issuance.",
          "status": "pass"
        }
      ],
      "negative_controls": [
        {
          "index": 0,
          "source_quotes": [
            "You must clear the applicant's pending name even though the name change is not final and even if the passport is not being issued at this time."
          ],
          "claim_ids": [],
          "rationale": "The negative control misinterprets the concessive clause 'even if the passport is not being issued at this time' as an exception that carves out the clearance requirement.",
          "status": "pass"
        }
      ],
      "uncertainty": "None observed."
    },
    {
      "id": "NREG-07",
      "invariants": [
        {
          "index": 0,
          "source_quotes": [
            "if the applicant has a name with multiple parts, you must determine how the name will appear:"
          ],
          "claim_ids": ["E017"],
          "rationale": "E017 faithfully models determining the appearance of a multipart name as a mandatory requirement with modality 'must'.",
          "status": "pass"
        },
        {
          "index": 1,
          "source_quotes": [
            "If the applicant's previous passport had a space, you should add a space on the current application;"
          ],
          "claim_ids": ["E018"],
          "rationale": "E018 models adding a space when a previous passport had a space as a recommendation with modality 'should'.",
          "status": "pass"
        },
        {
          "index": 2,
          "source_quotes": [
            "If the applicant does not have a previous passport and the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality or ID has a space, you should add a space on the current application;"
          ],
          "claim_ids": ["E019"],
          "rationale": "E019 preserves the recommendation force ('should') for the no-prior-passport condition.",
          "status": "pass"
        },
        {
          "index": 3,
          "source_quotes": [
            "If the applicant does not have a previous passport and the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality or ID has a space"
          ],
          "claim_ids": ["E019"],
          "rationale": "The compound logical condition (no previous passport AND [citizenship evidence OR ID has space]) is explicitly preserved in E019.",
          "status": "pass"
        },
        {
          "index": 4,
          "source_quotes": [
            "you should add a space on the current application;"
          ],
          "claim_ids": ["E018", "E019"],
          "rationale": "The draft maintains the distinction between recommendation ('should') and requirement ('must') without upgrading guidance to mandatory duty.",
          "status": "pass"
        }
      ],
      "negative_controls": [
        {
          "index": 0,
          "source_quotes": [
            "If the applicant's previous passport had a space, you should add a space on the current application;",
            "If the applicant does not have a previous passport and the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality or ID has a space, you should add a space on the current application;"
          ],
          "claim_ids": [],
          "rationale": "The negative control improperly upgrades advisory guidance ('should') to a mandatory duty ('must') and collapses the conditional structure into an overbroad rule.",
          "status": "pass"
        }
      ],
      "uncertainty": "None observed."
    }
  ]
}

source_quotes:
(1) Court orders or decrees:

(a) Name change orders; or

(b) Divorce decrees;
